{
  "packet_id": "H6-T02-1",
  "claim_id": "C007",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C007",
    "value": "Recording worker revision, configuration, dependencies, workspace size, object count and concurrency is proposed to prevent silent attribution of changes outside revision history to code.",
    "scope": "Rationale for recording revision and trial covariates; prevention is the proposed purpose.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 explicitly connects recording these variables with the purpose of avoiding silent attribution to code."
    }
  },
  "signal_basis": {
    "component_id": "C007_signal_basis",
    "value": "Worker revision and specified trial covariates are recorded, alongside per-revision tail-rate observations, uncertainty, workload and load, making possible alternative explanations available for comparison.",
    "scope": "Recorded context for interpreting revision comparisons; recording does not itself control confounding or establish causality.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the recorded variables and outcome observations and identify changing trial conditions as potential confounders."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C007_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The judgment is SUPPORTED; no conditional empirical relation component applies."
    }
  },
  "rationale": "Recording revision and trial context provides a basis for noticing changes outside code history. This licenses the stated preventive purpose. The frozen claim does not assert that recording guarantees correct attribution or removes confounding.",
  "uncertainty": "Whether investigators use the records effectively, and whether unrecorded factors remain, is unresolved but does not undermine the narrowly stated purpose.",
  "anomalies": []
}
